sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading) {
        return;
    }
    if (newValue != 'true' && newValue != '1') {
        return;
    }


    if (g_scratchpad.show_warning) {
        var tenantName = g_form.getDisplayValue('tenant');
        g_form.addErrorMessage(
            '⚠️ Warning: "' + tenantName + '" was not found in the latest WEX API response. ' +
            'It may have been manually created or deleted from WEX. ' +
            'Alert imports may fail if the Tenant ID is incorrect.'
        );
    }
}
